private func p1SizeCategoryReceipt(_ size: ContentSizeCategory) -> String {
    if size == .accessibilityExtraExtraExtraLarge { return "sizeCategory=AX5" }
    if size == .large { return "sizeCategory=default" }
    return "sizeCategory=other"
}

private struct P1RecoveryOperation {
    enum Phase { case prepared, dispatched }
    let kind = "install"
    let phase = Phase.dispatched
}

// These are deterministic inputs only. None of the callbacks communicates with
// SideStore, mutates durable recovery, or executes account/device operations.
@MainActor private final class P1RecoveryStatus: ObservableObject {
    @Published var kind: String
    @Published var largest: Bool
    @Published private(set) var lastAction = "none"
    private var actionSequence = 0
    let configuredKind: String
    init(kind: String) {
        self.kind = kind
        configuredKind = kind == "none" ? "operation" : kind
        largest = ProcessInfo.processInfo.arguments.contains("--largest")
    }
    func nextRecoveryKind() {
        let kinds = ["operation", "direct", "refresh", "unreadable"]
        let current = kinds.firstIndex(of: kind) ?? -1
        kind = kinds[(current + 1) % kinds.count]
    }
    func record(_ action: String) {
        actionSequence += 1
        lastAction = "\(action):\(actionSequence)"
    }
    var unresolvedOperationRecovery: P1RecoveryOperation? {
        kind == "operation" ? P1RecoveryOperation() : nil
    }
    var unresolvedDirectRecovery: V3HostDirectRecoveryRecord? {
        guard kind == "direct" else { return nil }
        return V3HostDirectRecoveryRecord([
            "requestID": "00000000-0000-0000-0000-000000000031",
            "operation": "certCreate", "phase": "prepared"
        ])
    }
    let directRecoveryPostcondition: V3DirectRecoveryPostcondition? = .manualCheckRequired
    let directRecoveryInspecting = false
    var unresolvedRefreshRecoveryRunID: String? {
        kind == "refresh" ? "00000000-0000-0000-0000-000000000031" : nil
    }
    var unresolvedRecoveryJournalUnreadable: Bool { kind == "unreadable" }
    let canDiscardUnreadableRecovery = true
    // Representative malformed-record strings match the production status text;
    // their values are synthetic, not evidence of service recovery state.
    let recoveryStorageTitle = "SideStore paused changes because its recovery record is malformed\nError ID: SS-STATUS-FIXTURE"
    let recoveryStorageGuidance = "Check the device before clearing this saved record. An earlier operation may still be running."
    let recoveryStorageDiagnosticCode = "SS-STATUS-FIXTURE"
    let recoveryStorageDiagnostics = "schema=1 operation=status stage=persistence recovery_storage_kind=malformedRecord"
    func resumeOperationRecovery() { record("resume-operation") }
    func reconcileDurableOperationAfterDeviceCheck() { record("reconcile-operation") }
    func inspectDirectRecovery() { record("inspect-direct") }
    func reconcileDirectRecoveryAfterUserCheck() { record("reconcile-direct") }
    func reconcileLostRefreshAfterDeviceCheck() { record("reconcile-refresh") }
    func discardUnreadableRecoveryAfterDeviceCheck() { record("discard-unreadable") }
}

@MainActor struct P1ProbeRecoveryScreen: View {
    @StateObject private var status: P1RecoveryStatus
    @State private var selectedTab = 0
    @State private var showOperationDeviceCheck = false
    @State private var showDirectRecoveryDeviceCheck = false
    @State private var showRefreshDeviceCheck = false
    @State private var showUnreadableRecoveryDeviceCheck = false

    init() {
        let arguments = ProcessInfo.processInfo.arguments
        let marker = arguments.firstIndex(of: "--recovery-kind")
        let kind = marker.flatMap { $0 + 1 < arguments.count ? arguments[$0 + 1] : nil } ?? "operation"
        precondition(["none", "operation", "direct", "refresh", "unreadable"].contains(kind))
        _status = StateObject(wrappedValue: P1RecoveryStatus(kind: kind))
    }

    var body: some View {
        // Match the production recovery host: TabView owns navigation children.
        // The exact reviewed modifier is applied to this outer TabView.
        TabView(selection: $selectedTab) {
            P1RecoveryNavigationRoot(status: status)
                .tabItem { Label("Home", systemImage: "house.fill") }.tag(0)
            P1RecoveryPlaceholderTab(title: "Apps")
                .tabItem { Label("Apps", systemImage: "square.stack.3d.up.fill") }.tag(1)
            P1RecoveryPlaceholderTab(title: "Sources")
                .tabItem { Label("Sources", systemImage: "books.vertical") }.tag(2)
            P1RecoveryPlaceholderTab(title: "Settings")
                .tabItem { Label("Settings", systemImage: "gearshape.fill") }.tag(3)
        }
        // Inactive production predecessors, explicitly synthetic substitutes.
        .safeAreaInset(edge: .bottom) { EmptyView() }
        .overlay(Color.clear.frame(width: 1, height: 1).allowsHitTesting(false).accessibilityHidden(true))
__P1_RECOVERY_MODIFIER__
        .environment(\.sizeCategory, status.largest ? .accessibilityExtraExtraExtraLarge : .large)
        .onReceive(NotificationCenter.default.publisher(for: UIPasteboard.changedNotification)) { _ in
            let expected = "diagnostic_code=\(status.recoveryStorageDiagnosticCode) builder_commit=\(V3DiagnosticBuild.commit)\n" + status.recoveryStorageDiagnostics
            if status.kind == "unreadable" && UIPasteboard.general.string == expected {
                status.record("copy-diagnostics-exact")
            }
        }
